export const googleMapsUrl = (query: string) => `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
export const totalNights = stays.filter((stay) => stay.includedInTripNights !== false).reduce((sum, stay) => sum + stay.nights, 0);
export const confirmedHotelTotalEUR = stays.filter((stay) => stay.status === 'booked').reduce((sum, stay) => sum + (stay.costEUR ?? 0), 0);
export const budgetTotals = budgetCategories.reduce((totals, category) => ({ low: totals.low + category.low, centre: totals.centre + category.centre, high: totals.high + category.high, confirmed: totals.confirmed + category.confirmed }), { low: 0, centre: 0, high: 0, confirmed: 0 });

